#!/usr/bin/env bun
/**
 * Diagnose auth issues running e2e tests.
 *
 * Usage:
 *   SUPERSERVE_API_KEY=ss_live_... bun tests/sdk-e2e-ts/scripts/diagnose-auth.ts
 *   SUPERSERVE_API_KEY=... SUPERSERVE_BASE_URL=https://api.superserve.ai bun tests/sdk-e2e-ts/scripts/diagnose-auth.ts
 *
 * What it does:
 *  1. Reports which env vars are set
 *  2. Tests the key against prod AND staging with raw curl-equivalent
 *  3. Calls Sandbox.create via the SDK and reports the result
 *  4. Tells you what's wrong
 */

import { Sandbox } from "@superserve/sdk"

const PROD = "https://api.superserve.ai"
const STAGING = "https://api-staging.superserve.ai"

const apiKey = [REDACTED]
const baseUrl = process.env.SUPERSERVE_BASE_URL

console.log("=== Env ===")
console.log(
  "SUPERSERVE_API_KEY:",
  apiKey
    ? `set (length=${apiKey.length}, prefix=${apiKey.slice(0, 8)}..., suffix=...${apiKey.slice(-4)})`
    : "NOT SET",
)
console.log("SUPERSERVE_BASE_URL:", baseUrl ?? "(default → prod)")

if (!apiKey) {
  console.error("\nSUPERSERVE_API_KEY is not set. Export it and try again.")
  process.exit(1)
}

async function probe(label: string, url: string): Promise<void> {
  try {
    const res = await fetch(`${url}/sandboxes`, {
      method: "GET",
      headers: { "X-API-Key": apiKey },
    })
    const body = await res.text()
    console.log(`  ${label} (${url}) → ${res.status}`)
    if (res.status !== 200) console.log(`    body: ${body.slice(0, 150)}`)
  } catch (err) {
    console.log(`  ${label} (${url}) → error: ${(err as Error).message}`)
  }
}

console.log("\n=== Raw fetch probe ===")
await probe("prod    ", PROD)
await probe("staging ", STAGING)

console.log("\n=== SDK probe (Sandbox.list) ===")
try {
  const list = await Sandbox.list({ apiKey, baseUrl })
  console.log(`  OK — returned ${list.length} sandboxes`)
} catch (err) {
  const e = err as Error
  console.log(`  FAIL — ${e.name}: ${e.message}`)
}

console.log("\n=== Diagnosis ===")
const resolved = baseUrl ?? PROD
if (resolved === PROD) {
  console.log("  Your SDK will hit PRODUCTION.")
  console.log(
    "  If the raw prod probe above returned 401, your key is not valid for production.",
  )
  console.log(
    "  If the raw staging probe returned 200, your key is for staging — set SUPERSERVE_BASE_URL=" +
      STAGING,
  )
} else {
  console.log("  Your SDK will hit:", resolved)
  console.log(
    "  If the raw probe at that URL returned 401, your key is not valid for that environment.",
  )
}

import { beforeEach, describe, expect, it, vi } from "vitest"

const mockSendToSlackHook = vi.fn()
vi.mock("@/lib/slack/send-to-webhook", () => ({
  default: (...args: unknown[]) => mockSendToSlackHook(...args),
}))

import { notifySlackOfNewUser } from "@/lib/slack/signup-notification"

describe("notifySlackOfNewUser", () => {
  beforeEach(() => {
    mockSendToSlackHook.mockReset().mockResolvedValue(undefined)
  })

  it("keeps identity fields and annotates the original payload", async () => {
    await notifySlackOfNewUser("user@example.com", "Test User", "google", {
      kind: "eligible",
    })

    expect(mockSendToSlackHook).toHaveBeenCalledWith(
      expect.objectContaining({
        text: expect.stringContaining(
          "✅ Signup Fingerprint eligible for first account in East",
        ),
        blocks: expect.arrayContaining([
          expect.objectContaining({
            type: "header",
            text: expect.objectContaining({ text: "New User Sign Up" }),
          }),
          expect.objectContaining({
            type: "section",
            fields: expect.arrayContaining([
              { type: "mrkdwn", text: "*Email:* user@example.com" },
              { type: "mrkdwn", text: "*Name:* Test User" },
              { type: "mrkdwn", text: "*Provider:* google" },
              {
                type: "mrkdwn",
                text: "*Signup Eligibility:* ✅ Signup Fingerprint eligible for first account in East",
              },
            ]),
          }),
        ]),
      }),
    )
  })

  it("uses safe blocked and unavailable annotations", async () => {
    await notifySlackOfNewUser("", null, "google", {
      kind: "blocked",
      reason: "blocked_email",
    })
    expect(mockSendToSlackHook.mock.calls[0][0].text).toContain(
      "❌ Signup blocked by configured signup restriction",
    )
    expect(mockSendToSlackHook.mock.calls[0][0].blocks).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          type: "section",
          fields: expect.arrayContaining([
            { type: "mrkdwn", text: "*Email:* N/A" },
            { type: "mrkdwn", text: "*Name:* N/A" },
            { type: "mrkdwn", text: "*Provider:* google" },
          ]),
        }),
      ]),
    )

    await notifySlackOfNewUser("user@example.com", null, "google")
    expect(mockSendToSlackHook.mock.calls[1][0].text).toContain(
      "Signup eligibility unavailable",
    )
  })

  it("contains webhook failures", async () => {
    mockSendToSlackHook.mockRejectedValueOnce(new Error("webhook down"))
    await expect(
      notifySlackOfNewUser("user@example.com", null, "email", {
        kind: "unavailable",
      }),
    ).resolves.toBeUndefined()
  })
})

/**
 * forgot-password action — critical safety test.
 *
 * The action MUST always return `{ success: true }`, regardless of whether
 * the email belongs to a real user, whether generateLink errors, whether
 * sendEmail throws, or whether the input is invalid. Any path that
 * discloses "this email exists / does not exist" is an email-enumeration
 * vulnerability.
 */

import { beforeEach, describe, expect, it, vi } from "vitest"

const mockGenerateLink = vi.fn()
const mockSendEmail = vi.fn()

vi.mock("@/lib/supabase/admin", () => ({
  createAdminClient: () => ({
    auth: {
      admin: { generateLink: mockGenerateLink },
    },
  }),
}))

vi.mock("@/lib/email/send", () => ({
  sendEmail: (...args: unknown[]) => mockSendEmail(...args),
}))

vi.mock("@/lib/email/templates/password-reset", () => ({
  PasswordResetEmail: () => null,
}))

import { sendPasswordResetEmail } from "./action"

describe("sendPasswordResetEmail", () => {
  beforeEach(() => {
    mockGenerateLink.mockReset()
    mockSendEmail.mockReset()
  })

  it("returns success for a valid email + happy path", async () => {
    mockGenerateLink.mockResolvedValue({
      data: { properties: { hashed_token: "token-abc" } },
      error: null,
    })
    mockSendEmail.mockResolvedValue(undefined)

    const result = await sendPasswordResetEmail("user@example.com")

    expect(result).toEqual({ success: true })
    expect(mockGenerateLink).toHaveBeenCalledWith(
      expect.objectContaining({
        type: "recovery",
        email: "user@example.com",
      }),
    )
    expect(mockSendEmail).toHaveBeenCalledTimes(1)
  })

  it("returns success for an invalid email without calling Supabase", async () => {
    const result = await sendPasswordResetEmail("not-an-email")
    expect(result).toEqual({ success: true })
    expect(mockGenerateLink).not.toHaveBeenCalled()
    expect(mockSendEmail).not.toHaveBeenCalled()
  })

  it("returns success when Supabase generateLink errors (no enumeration leak)", async () => {
    mockGenerateLink.mockResolvedValue({
      data: null,
      error: { message: "User not found" },
    })

    const result = await sendPasswordResetEmail("ghost@example.com")

    expect(result).toEqual({ success: true })
    expect(mockSendEmail).not.toHaveBeenCalled()
  })

  it("returns success when generateLink returns data without a hashed token", async () => {
    mockGenerateLink.mockResolvedValue({
      data: { properties: {} },
      error: null,
    })

    const result = await sendPasswordResetEmail("user@example.com")

    expect(result).toEqual({ success: true })
    expect(mockSendEmail).not.toHaveBeenCalled()
  })

  it("returns success when sendEmail throws", async () => {
    mockGenerateLink.mockResolvedValue({
      data: { properties: { hashed_token: "token-abc" } },
      error: null,
    })
    mockSendEmail.mockRejectedValue(new Error("SMTP down"))

    const result = await sendPasswordResetEmail("user@example.com")

    expect(result).toEqual({ success: true })
  })

  it("returns success when the admin client throws synchronously", async () => {
    mockGenerateLink.mockImplementation(() => {
      throw new Error("boom")
    })

    const result = await sendPasswordResetEmail("user@example.com")

    expect(result).toEqual({ success: true })
  })

  it("builds the reset URL with token_hash + type=recovery", async () => {
    mockGenerateLink.mockResolvedValue({
      data: { properties: { hashed_token: "hash-xyz" } },
      error: null,
    })
    mockSendEmail.mockResolvedValue(undefined)

    await sendPasswordResetEmail("user@example.com")

    const call = mockSendEmail.mock.calls[0][0] as {
      to: string
      subject: string
      react: unknown
    }
    expect(call.to).toBe("user@example.com")
    expect(call.subject).toContain("Reset")
  })

  it.each([
    ["an account awaiting Enterprise setup", { signup_review: "pending" }],
    ["a rejected account", { signup_review: "rejected" }],
  ])(
    "returns success without sending a link to %s",
    async (_label, app_metadata) => {
      mockGenerateLink.mockResolvedValue({
        data: {
          user: { id: "user-1", app_metadata },
          properties: { hashed_token: "token-abc" },
        },
        error: null,
      })

      const result = await sendPasswordResetEmail("user@example.com")

      expect(result).toEqual({ success: true })
      expect(mockSendEmail).not.toHaveBeenCalled()
    },
  )

  it("still sends recovery to an unconfirmed account without a hold", async () => {
    mockGenerateLink.mockResolvedValue({
      data: {
        user: { id: "user-1", email_confirmed_at: null, app_metadata: {} },
        properties: { hashed_token: "token-abc" },
      },
      error: null,
    })
    mockSendEmail.mockResolvedValue(undefined)

    await sendPasswordResetEmail("user@example.com")

    expect(mockSendEmail).toHaveBeenCalledOnce()
  })
})

import crypto from "node:crypto"

import { beforeEach, describe, expect, it, vi } from "vitest"

let activeTeam: { teamId: string; region: string } | null = {
  teamId: "team-1",
  region: "use",
}
vi.mock("@/lib/api/active-team", () => ({
  readTeamSelection: async () => null,
  pickActiveTeam: (memberships: Array<NonNullable<typeof activeTeam>>) =>
    memberships[0] ?? null,
}))
vi.mock("@/lib/api/team-directory", () => ({
  listTeamMembershipsForUserDetailed: async () => ({
    memberships: activeTeam ? [activeTeam] : [],
    degradedRegions: [],
  }),
  invalidateMembershipDirectory: vi.fn(),
}))
vi.mock("@/lib/api/team-provisioning", () => ({
  completedMemberships: vi.fn(
    async (
      _userId: string,
      directory: import("@/lib/api/team-directory").MembershipDirectory,
    ) => directory,
  ),
  provisionTeam: vi.fn(),
}))

vi.mock("@/lib/admin/impersonation", () => ({
  getImpersonationTeamId: async () => null,
}))
vi.mock("@/lib/supabase/server", () => ({
  createServerClient: async () => ({
    auth: {
      getUser: async () => ({
        data: { user: { id: "a1", email: "amit@superserve.ai" } },
      }),
    },
  }),
}))

// No cookie set: active-team resolution falls back to the first membership.
vi.mock("next/headers", () => ({
  cookies: async () => ({ get: () => undefined }),
}))

// Per-test knobs read lazily by the admin-client mock.
let homeRegionResult: { data: unknown; error: unknown } = {
  data: { home_region: "usw" },
  error: null,
}
let insertedApiKeyRow: Record<string, unknown> | null = null

// Minimal chainable stub: every builder method returns the chain; single()
// resolves to the configured result.
function chain(result: { data: unknown; error: unknown }) {
  const c: Record<string, unknown> = {}
  for (const m of ["select", "eq", "is", "neq", "order", "limit", "update"]) {
    c[m] = () => c
  }
  c.single = async () => result
  c.maybeSingle = async () => result
  return c
}

vi.mock("@/lib/supabase/admin", () => ({
  createAdminClient: () => ({
    from: (table: string) => {
      switch (table) {
        case "profile":
          return chain({ data: { id: "a1" }, error: null })
        case "team_memberships":
          return chain({ data: [], error: null })
        case "team_member":
          // The membership fan-out awaits the filter directly (no single()).
          return {
            select: () => ({
              eq: async () => ({ data: [{ team_id: "team-1" }], error: null }),
            }),
          }
        case "team":
          return chain(homeRegionResult)
        case "api_key": {
          const c = chain({
            data: { id: "k1", name: "test", created_at: "2026-07-01" },
            error: null,
          }) as Record<string, unknown> & {
            insert?: (row: Record<string, unknown>) => unknown
          }
          c.insert = (row: Record<string, unknown>) => {
            insertedApiKeyRow = row
            return c
          }
          return c
        }
        default:
          throw new Error(`unexpected table ${table}`)
      }
    },
  }),
}))

import {
  completedMemberships,
  provisionTeam,
} from "@/lib/api/team-provisioning"
import {
  SignupRestrictedError,
  SIGNUP_RESTRICTED_MESSAGE,
} from "@/lib/auth/signup-restrictions"

import {
  createApiKeyAction,
  listApiKeysAction,
  revokeApiKeyAction,
} from "./api-keys-actions"

async function createAllowedKey(name: string) {
  const result = await createApiKeyAction(name)
  if ("code" in result) throw new Error(result.message)
  return result
}

describe("createApiKeyAction region-prefixed keys", () => {
  beforeEach(() => {
    insertedApiKeyRow = null
    activeTeam = { teamId: "team-1", region: "use" }
    vi.mocked(completedMemberships).mockImplementation(
      async (_userId, directory) => directory,
    )
    vi.mocked(provisionTeam).mockReset()
  })

  it("does not create a key when first-team provisioning is blocked", async () => {
    activeTeam = null
    vi.mocked(provisionTeam).mockRejectedValueOnce(new SignupRestrictedError())

    await expect(createApiKeyAction("blocked")).resolves.toEqual({
      code: "signup_blocked",
      message: SIGNUP_RESTRICTED_MESSAGE,
    })
    expect(provisionTeam).toHaveBeenCalledOnce()
    expect(insertedApiKeyRow).toBeNull()

    activeTeam = { teamId: "team-1", region: "use" }
    const key = await createAllowedKey("established")
    expect(key.key).toMatch(/^ss_live_/)
    expect(provisionTeam).toHaveBeenCalledOnce()
    expect(insertedApiKeyRow).toMatchObject({
      team_id: "team-1",
      name: "established",
      created_by: "a1",
    })
  })

  it("returns the same denial for lazy list and revoke paths", async () => {
    activeTeam = null
    vi.mocked(provisionTeam).mockRejectedValue(new SignupRestrictedError())

    const denial = {
      code: "signup_blocked",
      message: SIGNUP_RESTRICTED_MESSAGE,
    }
    await expect(listApiKeysAction()).resolves.toEqual(denial)
    await expect(revokeApiKeyAction("key-1")).resolves.toEqual(denial)
    expect(insertedApiKeyRow).toBeNull()
  })

  it("does not mint a key from an unfinished owner membership after failed cleanup", async () => {
    activeTeam = { teamId: "unfinished-team", region: "use" }
    vi.mocked(completedMemberships).mockImplementation(
      async (_userId, directory) => ({ ...directory, memberships: [] }),
    )
    vi.mocked(provisionTeam).mockRejectedValueOnce(new SignupRestrictedError())

    await expect(createApiKeyAction("retry")).resolves.toEqual({
      code: "signup_blocked",
      message: SIGNUP_RESTRICTED_MESSAGE,
    })
    expect(completedMemberships).toHaveBeenCalledWith(
      "a1",
      expect.objectContaining({ memberships: [activeTeam] }),
    )
    expect(provisionTeam).toHaveBeenCalledWith(
      "use",
      "a1",
      "amit@superserve.ai",
      "amit@superserve.ai",
      {
        user: expect.objectContaining({ id: "a1" }),
        observedAt: expect.any(String),
      },
    )
    expect(insertedApiKeyRow).toBeNull()
  })

  it("mints a key carrying the team's home region", async () => {
    homeRegionResult = { data: { home_region: "usw" }, error: null }
    const res = await createAllowedKey("test")

    expect(res.key).toMatch(/^ss_live_usw_[A-Za-z0-9_-]{32}$/)
    // Exactly 8 random chars after the region segment.
    const randomPart = res.key.slice("ss_live_usw_".length)
    expect(res.prefix).toBe(`ss_live_usw_${randomPart.slice(0, 8)}...`)
    // Stored hash covers the full key string, region segment included.
    const wantHash = crypto.createHash("sha256").update(res.key).digest("hex")
    expect(insertedApiKeyRow?.key_hash).toBe(wantHash)
  })

  it("falls back to the default region when home_region is missing", async () => {
    // Simulates the column not existing yet (migration not applied).
    homeRegionResult = {
      data: null,
      error: { message: "column team.home_region does not exist" },
    }
    const res = await createAllowedKey("test")
    expect(res.key).toMatch(/^ss_live_use_/)
  })

  it("falls back to the default region on an unknown region code", async () => {
    homeRegionResult = { data: { home_region: "mars" }, error: null }
    const res = await createAllowedKey("test")
    expect(res.key).toMatch(/^ss_live_use_/)
  })
})

