        email: "existing@example.com",
      } as never),
    ).rejects.toThrow("Membership lookup degraded; please try again")

    expect(provisionTeam).not.toHaveBeenCalled()
    expect(useApiKeyUpserts).toEqual([])
  })

  it("does not provision when the initial non-Google membership read is degraded", async () => {
    vi.mocked(listTeamMembershipsForUserDetailed).mockResolvedValueOnce({
      memberships: [],
      degradedRegions: ["usw"],
    })

    await expect(
      getAuthApiKeyForUser({
        id: "degraded-initial-user",
        email: "existing@example.com",
      } as never),
    ).rejects.toThrow("Membership lookup degraded; please try again")

    expect(provisionTeam).not.toHaveBeenCalled()
    expect(useApiKeyUpserts).toEqual([])
  })

  it("uses a detailed Google membership read when the initial lookup is empty", async () => {
    vi.mocked(listTeamMembershipsForUserDetailed)
      .mockResolvedValueOnce({ memberships: [], degradedRegions: [] })
      .mockResolvedValueOnce({
        memberships: [{ teamId: "team-west", region: "usw" }],
        degradedRegions: ["use"],
      })

    const key = await getAuthApiKeyForUser({
      id: "google-user",
      email: "google@example.com",
      app_metadata: { provider: "google", providers: ["google"] },
    } as never)

    expect(key).toMatch(/^ss_live_/)
    expect(provisionTeam).not.toHaveBeenCalled()
  })

  it("respects the selected active team when recovering a fresh Google lookup", async () => {
    vi.mocked(listTeamMembershipsForUserDetailed)
      .mockResolvedValueOnce({ memberships: [], degradedRegions: [] })
      .mockResolvedValueOnce({
        memberships: [
          { teamId: "team-east", region: "use" },
          { teamId: "team-west", region: "usw" },
        ],
        degradedRegions: [],
      })
    activeTeamCookie = "usw:team-west"

    const key = await getAuthApiKeyForUser({
      id: "google-selected-user",
      email: "google@example.com",
      app_metadata: { provider: "google", providers: ["google"] },
    } as never)

    expect(key).toMatch(/^ss_live_/)
    expect(provisionTeam).not.toHaveBeenCalled()
  })

  it("fails transiently when a degraded empty lookup cannot be recovered", async () => {
    vi.mocked(listTeamMembershipsForUserDetailed)
      .mockResolvedValueOnce({ memberships: [], degradedRegions: [] })
      .mockResolvedValueOnce({
        memberships: [],
        degradedRegions: ["use"],
      })
    await expect(
      getAuthApiKeyForUser({
        id: "google-indeterminate-user",
        email: "google@example.com",
        app_metadata: { provider: "google", providers: ["google"] },
      } as never),
    ).rejects.toThrow("Google membership lookup degraded; please try again")

    expect(provisionTeam).not.toHaveBeenCalled()
  })
})

describe("proxy-auth impersonation", () => {
  beforeEach(() => {
    vi.mocked(platformImpersonationReadScopes).mockReset()
    vi.mocked(ensureImpersonationKeyRow).mockReset()
  })

  it("mints an impersonation key with the canonical read scopes", async () => {
    vi.mocked(platformImpersonationReadScopes).mockReturnValue([
      "platform:sandbox:read",
      "platform:template:read",
      "platform:activity:read",
    ])
    vi.mocked(ensureImpersonationKeyRow).mockResolvedValue(
      "ss_live_impersonation",
    )

    const key = await getAuthApiKeyForUser(
      { id: "admin", email: "admin@superserve.ai" } as never,
      "team-1",
    )

    expect(key).toBe("ss_live_impersonation")
    expect(ensureImpersonationKeyRow).toHaveBeenCalledWith(
      "admin",
      "team-1",
      "use",
      [
        "platform:sandbox:read",
        "platform:template:read",
        "platform:activity:read",
      ],
      expect.any(Number),
    )
  })

  it("uses the impersonation region without re-resolving it", async () => {
    vi.mocked(platformImpersonationReadScopes).mockReturnValue([
      "platform:sandbox:read",
    ])

    await getAuthApiKeyForUser(
      { id: "admin", email: "admin@superserve.ai" } as never,
      {
        teamId: "team-1",
        region: "usw",
      },
    )

    expect(ensureImpersonationKeyRow).toHaveBeenCalledWith(
      "admin",
      "team-1",
      "usw",
      ["platform:sandbox:read"],
      expect.any(Number),
    )
  })

  it("rejects impersonation when no supported scopes are available", async () => {
    vi.mocked(platformImpersonationReadScopes).mockReturnValue([])

    await expect(
      getAuthApiKeyForUser(
        { id: "admin", email: "admin@superserve.ai" } as never,
        "team-1",
      ),
    ).rejects.toThrow(
      /impersonation requires a supported platform read permission/,
    )
  })
})

import { expect, it } from "vitest"

import {
  financialAuthoritySchema,
  financialRevocationMessage,
} from "./financial-authority"

it("distinguishes pending regional acknowledgment from confirmed revocation", () => {
  const pending = financialAuthoritySchema.parse({
    kind: "accepted_offer",
    state: "revocation_pending",
    pending_invalidations: 2,
  })
  const confirmed = financialAuthoritySchema.parse({
    kind: "accepted_offer",
    state: "revoked",
    pending_invalidations: 0,
  })
  expect(financialRevocationMessage(pending)?.title).toBe("Revocation pending")
  expect(financialRevocationMessage(confirmed)?.title).toBe(
    "Revocation confirmed",
  )
  expect(financialRevocationMessage(pending)?.description).toContain(
    "New activation is blocked",
  )
  expect(financialRevocationMessage(confirmed)?.description).toContain(
    "does not confirm cancellation or a refund",
  )
})
it.each(["acceptance_pending", "valid", "revoked"])(
  "rejects %s while financial acknowledgments remain outstanding",
  (state) => {
    expect(
      financialAuthoritySchema.safeParse({
        kind: "accepted_offer",
        state,
        pending_invalidations: 1,
      }).success,
    ).toBe(false)
  },
)
it("leaves legacy null and valid authorization presentation unchanged", () => {
  expect(
    financialRevocationMessage(financialAuthoritySchema.parse(null)),
  ).toBeNull()
  expect(
    financialRevocationMessage({
      kind: "accepted_offer",
      state: "valid",
      pending_invalidations: 0,
    }),
  ).toBeNull()
})

it("does not confuse acceptance pending with revocation or readiness", () => {
  const authority = financialAuthoritySchema.parse({
    kind: "accepted_offer",
    state: "acceptance_pending",
    pending_invalidations: 0,
  })
  expect(financialRevocationMessage(authority)).toBeNull()
})
